end

function TrailStageChallenge:Awake()
    self.EventRefeshTrailQuestDialog = Events.AddListener(Constants.EventNames.RefeshTrailQuestDialog, Bind(self, self.FreshBaseUI))
    self.EventRefeshTeamMember = Events.AddListener(Constants.EventNames.RefeshTeamMember, Bind(self, self.FreshBaseUI))

    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnOneKeyTeamSetting))
    SetButtonAction(self.FontStyleButton2, Bind(self, self.OnBtnFight))
    self:FreshBaseUI()
end

function TrailStageChallenge:ResetAnimData()
    for i = 1, LoopViewMaxCellCount do
        self["isAnimated"..i] = false
