function TrailStageChallenge:FreshLoopView()
    if not self.TeamList.IsListViewInit then
        self.TeamList:InitListView(#self.questIds, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.TeamList, #self.questIds)
    end
end

function TrailStageChallenge:GetConditionRestrictData(conditionId)
    for k, v in pairs(self.restrictIds) do
        local restrictVo = CfUtils.GetCfVo(AutoIds.IdSetting744, "TrailQuestRestrictVo", v)
        if checkNumber(restrictVo.condition1) == checkNumber(conditionId) then
            return restrictVo
        end
    end
    return {}
end

function TrailStageChallenge:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local nodeEnv = CfUtils.GetLuaScr(cell.gameObject, "Game.UI.TrailStage.TrailStageChallengeCell")
    if nodeEnv then
        local luaIndex = index + 1
        local data = self.questIds[luaIndex]
        --@region 刚进入列表时播放延时出现动画
        if not isNull(self["isAnimated"..luaIndex]) then
            if not self["isAnimated"..luaIndex] then
                self["isAnimated"..luaIndex] = true
                CfUtils.PlayDelayShowAnimate(cell.transform:Find("AnimRoot"), luaIndex)
            else
                CfUtils.PlayDelayShowAnimate(cell.transform:Find("AnimRoot"), 0)
            end
        else
            CfUtils.PlayDelayShowAnimate(cell.transform:Find("AnimRoot"), 0)
        end
        --@endregion
        nodeEnv:FreshBaseUI(data, luaIndex)
    end
    return cell
end

--一键编队
function TrailStageChallenge:OnBtnOneKeyTeamSetting()
    local cards = cardComponent:GetAllCardTable()
    local t = CardUtils.SortCardBySortType(cards, Constants.SortType.CombatPower, true)
    local cardIndex = 1   --选人的下标
    local teamInfo = {}
    for i, v in pairs(self.questIds) do
        local isUnlock = trailBattleMgr:IsUnlockQuest(i)
        if isUnlock then
            local memberNum = teamComponent:GetMaxSelectNum(v, Constants.ChooseCardStatus.Normal, i) --初始空位数量
            teamInfo[i] = {
                cardsInfo = {}
            }
            if cardIndex <= table.count(t) then
                local count = 0
                for _ind = cardIndex, table.count(t) do
                    local cardData = t[_ind]
                    --添加到编队中
                    local refId = cardData.id
                    local type = Constants.TeamMemberType.PlayerCard
                    table.insert(teamInfo[i].cardsInfo, CfUtils.GetTeamMemberDojo{
                        type = type,
                        refId = refId
                    })
                    count = count + 1
                    cardIndex = cardIndex + 1
                    if count >= memberNum then
                        break
                    end
                end
                if count < memberNum then
                    for j = count + 1, memberNum do
                        table.insert(teamInfo[i].cardsInfo, {})
                    end
                end
            else
                for j = 1, memberNum do
                    table.insert(teamInfo[i].cardsInfo, {})
                end
            end
            teamComponent:SetTeamByQuestId(v, teamInfo[i].cardsInfo, nil, i)
        end
    end

end

--开始战斗
function TrailStageChallenge:OnBtnFight()
    local isCanBattle, errStr = self:IsCanBattle()
    if not isCanBattle then
        GameUtils.Toast(errStr)
        return
    end
    for i, v in pairs(self.questIds) do
        local isUnlock = trailBattleMgr:IsUnlockQuest(i)
        if isUnlock then
            teamComponent:SetTeamReq(v, function()
                local isUnlockNext = trailBattleMgr:IsUnlockQuest(i + 1)
                if not isUnlockNext then
                    cs_coroutine.start(function()
                        self.controller:SetBackArgument(true)
                        fightPreWarMgr:FightEnter(self.questIds[1])
                    end)
                end
            end)
        end
    end
end

--是否可以战斗
function TrailStageChallenge:IsCanBattle()
    local isHaveMember = false
    local err = localize("队伍不能为空")
    for i, v in pairs(self.questIds) do
        local isUnlock = trailBattleMgr:IsUnlockQuest(i)
        if isUnlock then
            local t = teamComponent:GetTeamByQuestId(v, i)
            local count = teamComponent:GetTeamMemberCount(t)
            if count > 0 then
                isHaveMember = true
            else
                isHaveMember = false
                break
            end
        end
    end
    return isHaveMember, err
end

function TrailStageChallenge:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.RemoveListener(Constants.EventNames.RefeshTrailQuestDialog, self.EventRefeshTrailQuestDialog)
        Events.RemoveListener(Constants.EventNames.RefeshTeamMember, self.EventRefeshTeamMember)

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return TrailStageChallenge